const names={1:'Clear & Confident',2:'Editorial Academy',3:'Course Navigator',4:'Community Focus'};
const choice=document.querySelector('#choice'),feedback=document.querySelector('#feedback'),status=document.querySelector('#choice-status');
function save(){try{localStorage.setItem('aifl-design-review',JSON.stringify({choice:choice.value,feedback:feedback.value}))}catch{}}
function update(){document.querySelectorAll('[data-choose]').forEach(button=>{const selected=button.dataset.choose===choice.value;button.setAttribute('aria-pressed',String(selected));button.textContent=selected?'Selected option 0'+button.dataset.choose:'Choose option 0'+button.dataset.choose});save()}
try{const saved=JSON.parse(localStorage.getItem('aifl-design-review')||'{}');if(names[saved.choice])choice.value=saved.choice;if(typeof saved.feedback==='string')feedback.value=saved.feedback}catch{}
const requested=new URLSearchParams(location.search).get('choose');if(names[requested])choice.value=requested;update();
document.querySelectorAll('[data-choose]').forEach(button=>button.addEventListener('click',()=>{choice.value=button.dataset.choose;update();status.textContent='Option 0'+choice.value+' selected. Add your feedback below.';document.querySelector('#your-choice').scrollIntoView({behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'instant':'smooth'});choice.focus({preventScroll:true})}));
choice.addEventListener('change',update);feedback.addEventListener('input',save);
document.querySelector('#choice-form').addEventListener('submit',async event=>{event.preventDefault();if(!names[choice.value]){choice.reportValidity();return}const base=new URL('review.html',location.href);base.searchParams.set('option',choice.value);const text=`AIFL website design feedback\n\nPreferred direction: 0${choice.value} — ${names[choice.value]}\nPreview: ${base.href}\n\nFeedback: ${feedback.value.trim()||'No additional feedback.'}`;try{await navigator.clipboard.writeText(text);status.textContent='Copied. Paste this into your message to the designer.';document.querySelector('#copy-fallback').hidden=true}catch{const fallback=document.querySelector('#copy-fallback');fallback.hidden=false;fallback.value=text;fallback.focus();fallback.select();status.textContent='Select and copy the text below, then send it to the designer.'}});
